from PIL import Image
import numpy as np, os
for c in (0,1,2):
 p=f'/app/output/limited-view-{c}.jpg'
 if not os.path.exists(p):
  print(p,'missing'); continue
 a=np.asarray(Image.open(p).convert('RGB'))
 print('camera',c)
 if c==0:
  # Interior samples: upper/rear panel and lower/front panel
  regions={'upper':(180,325,270,370),'lower':(300,390,390,450)}
 elif c==2:
  regions={'left':(10,160,65,210),'right':(95,150,175,205)}
 else:
  regions={'panel':(300,280,430,310)}
 for name,(x1,y1,x2,y2) in regions.items():
  q=a[y1:y2,x1:x2]
  print(name,'mean RGB',q.mean((0,1)).round(1),'median',np.median(q.reshape(-1,3),axis=0),'pixels',q.shape[:2])
