import limited_client as robot
import numpy as np
for c in (0,2):
 o=robot.observe(camera=c); r=o['robot']; K=o['intrinsic']; T=o['camera_to_world']
 print('\nCAM',c,'tcp',r['tcp_position'],'gripper',r['gripper_positions'],'joints',r['joint_positions'])
 print('K',K.tolist(),'T',T.tolist())
 if c==0:
  pixels={'panel_left':(225,365),'panel_right':(375,405)}
 else:
  pixels={'panel_left':(45,190),'panel_right':(145,190)}
 for name,(u,v) in pixels.items():
  z=float(o['depth_m'][v,u]); p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1.])
  print(name,'pixel',(u,v),'depth',z,'world',(T@p)[:3].round(4).tolist(),'rgb',o['rgb'][v,u].tolist())
print('STATUS',robot.status())
